%% DATU ESPERIMENTALEN KUDEAKETAclearJ=[188*10^-6 156*10^-6;195*10^-6 154*10^-6;200*10^-6 151*10^-6;208*10^-6 147*10^-6;218*10^-6 142*10^-6;228*10^-6 137*10^-6;233*10^-6 131*10^-6;236*10^-6 125*10^-6;238*10^-6 119*10^-6;228*10^-6 113*10^-6;215*10^-6 108*10^-6];R=[1.4*10^-5 1.85*10^-5;1.5*10^-5 1.71*10^-5;1.7*10^-5 1.58*10^-5;1.8*10^-5 1.45*10^-5;2.05*10^-5 1.33*10^-5;2.25*10^-5 1.21*10^-5;2.4*10^-5 1.1*10^-5;2.6*10^-5 1.01*10^-5;2.6*10^-5 0.93*10^-5;2.35*10*-5 0.84*10^-5;2.1*10^-5 0.75*10^-5];K=[0.965 0.8;0.915 0.78;0.875 0.77;0.84 0.77;0.81 0.77;0.79 0.79;0.79 0.81;0.795 0.83;0.805 0.86;0.81 0.91;0.82 0.96];L=flipud(J(:,1));L=transpose(L);M=flipud(J(:,2));M=transpose(M);P=flipud(R(:,1));P=transpose(P);V=flipud(R(:,2));V=transpose(V);T=flipud(K(:,1));T=transpose(T);U=flipud(K(:,2));U=transpose(U);n=10;x=linspace(300,550,n+1);L1=(L(2)-L(1))/(x(2)-x(1));L2=(L(n+1)-L(n))/(x(n+1)-x(n));x0=L1;xn=L2;i=90figure(i)[r1,y1]=splinekubik(x,L,3,x0,xn);hold onM1=(M(2)-M(1))/(x(2)-x(1));M2=(M(n+1)-M(n))/(x(n+1)-x(n));x0=M1;xn=M2;[r2,y2]=splinekubik(x,M,3,x0,xn);P(2)=2.35*10^-5;P1=(P(2)-P(1))/(x(2)-x(1));P2=(P(n+1)-P(n))/(x(n+1)-x(n));x0=P1;xn=P2;i=91figure(i)[r3,y3]=splinekubik(x,P,3,x0,xn);hold onV1=(V(2)-V(1))/(x(2)-x(1));V2=(V(n+1)-V(n))/(x(n+1)-x(n));x0=V1;xn=V2;[r4,y4]=splinekubik(x,V,3,x0,xn);T1=(T(2)-T(1))/(x(2)-x(1));T2=(T(n+1)-T(n))/(x(n+1)-x(n));x0=T1;xn=T2;i=92figure(i)[r5,y5]=splinekubik(x,T,3,x0,xn);hold onU1=(U(2)-U(1))/(x(2)-x(1));U2=(U(n+1)-U(n))/(x(n+1)-x(n));x0=U1;xn=U2;[r6,y6]=splinekubik(x,U,3,x0,xn);i=93;izena1='p-Mg(0.0995)Yb(0.005)Ag(0.97)Sb(0.99)'izena2='n-Bi(0.5)Sb(1.5)Te(0.9)Se(0.3)'figure(i)plot(r1,y1,'-b')ylabel('Valores de coeficiente de Seebeck[V/K]')xlabel('Diferentes temperaturas [K]')title("Valores del coeficiente de Seebeck para diferentes temperaturas")      hold onplot(r2,y2,'-g')legend(izena1,izena2,'Location','southoutside')      legend('boxoff')      grid on        print(figure(i),'TFGprops')i=94;figure(i)plot(r3,y3,'-b')ylabel('Valores de resistividad electrica [Ohm/m]')xlabel('Diferentes temperaturas [K]')title("Valores de resistividad para diferentes temperaturas")hold onplot(r4,y4,'-g')legend(izena1,izena2,'Location','southoutside')      legend('boxoff')      grid on        print(figure(i),'TFGprope')i=95;figure(i)plot(r5,y5,'-b')ylabel('Valores de conductividad termica [W/mK]')xlabel('Diferentes temperaturas [K]')title("Valores de coeficientes de conductividad termica para diferentes temperaturas")hold onplot(r6,y6,'-g')legend(izena1,izena2,'Location','southoutside')      legend('boxoff')      grid on        print(figure(i),'TFGpropero')      T_hot=700       %[K]T_cold=300      %[K]numeros=[T_hot,T_cold]T_b=mean(numeros)        %[K]T_prop=(T_hot-T_cold)/log(T_hot/T_cold)    %[K]Tdif=T_hot-T_cold;N=1;      %cantidad p-n par Lp=0.005;    %Medida del material p en dirección verticalLn=0.005;    %Medida del material n en dirección verticalp=25;        %Saltos térmicos de cuanto?disp('Primera opcion,opt=1,gemometria planar eta segunda opcion, opt=2, geometria tubular')opt=1lim=25;      %Para determinar el último valor del salto térmicoj=(Tdif-lim)/p;       %Para imprimir una cantidad de saltos térmicosif opt==1Ap=0.025*0.025  %Área de la superficie de material termoeléctrico tipo pAn=0.025*0.025  %Área de la superficie de material termoeléctrico tipo nLuzera_TEG=N*0.015%%% Para el coeficiente de SeebeckSp_b=aurkitu(T_b,r1,y1)Sn_b=aurkitu(T_b,r2,y2)%%% Para el coeficiente de resistividad eléctricaRp_b=aurkitu(T_b,r3,y3)Rn_b=aurkitu(T_b,r4,y4)%%% Para el coeficiente de conductividad térmicaKp_b=aurkitu(T_b,r5,y5)Kn_b=aurkitu(T_b,r6,y6)izena=('p-Mg(0.995)Yb(0.005)Ag(0.97)Sb(0.99) ; n-Bi(0.5)Sb(1.5)Te(0.9)Se(0.3)')Q=berop(0,100,Sp_b,Sn_b,Rp_b,Rn_b,Tdif,Ap,An,Lp,Ln,Kp_b,Kn_b,T_cold,j);W=welek(0,100,Sp_b,Sn_b,Rp_b,Rn_b,Tdif,Ap,An,Lp,Ln,Kp_b,Kn_b,j);grafikoa4(0,100,Q,W,Tdif,izena,1)elseerradio_1=0.3;erradio_2=0.35;Ap=pi*(erradio_2^2-erradio_1^2);An=pi*(erradio_2^2-erradio_1^2);Luzera_TEG=N*0.015%%% Para el coeficiente de SeebeckSp_prop=aurkitu(T_prop,r1,y1)Sn_prop=aurkitu(T_prop,r2,y2)%%% Para el coeficiente de resistividad eléctricaRp_prop=aurkitu(T_prop,r3,y3)Rn_prop=aurkitu(T_prop,r4,y4)%%% Para el coeficiente de conductividad térmicaKp_prop=aurkitu(T_prop,r5,y5)Kn_prop=aurkitu(T_prop,r6,y6)izena=('p-Mg(0.995)Yb(0.005)Ag(0.97)Sb(0.99) ; n-Bi(0.5)Sb(1.5)Te(0.9)Se(0.3)')Q=berop(0,100,Sp_prop,Sn_prop,Rp_prop,Rn_prop,Tdif,Ap,An,Lp,Ln,Kp_prop,Kn_prop,T_cold,j);W=welek(0,100,Sp_prop,Sn_prop,Rp_prop,Rn_prop,Tdif,Ap,An,Lp,Ln,Kp_prop,Kn_prop,j);grafikoa4(0,100,Q,W,Tdif,izena,1)end[kontador,potentzia_elek]=grafikoa2(0,100,Sp_b,Sn_b,Rp_b,Rn_b,Tdif,N,Ap,An,Lp,Ln,izena,j,p,r1,y1,r2,y2,r3,y3,r4,y4,r5,y5,r6,y6,T_cold,opt)[hasierakoK,l,limK,beropotentzia,paso,kontador]=grafikoa6(0,100,Sp_b,Sn_b,Rp_b,Rn_b,Tdif,N,Ap,An,Lp,Ln,Kp_b,Kn_b,izena,j,p,r1,y1,r2,y2,r3,y3,r4,y4,r5,y5,r6,y6,T_cold,opt,kontador)## x=linspace(hasierakoK,limK,l);##   ## F_batazbeste=((potentzia_elek)./(beropotentzia))*100;## max(F_batazbeste)##   figure(100)##     plot(x,F_batazbeste)##      xlabel("I (A)")##      ylabel("Errendimendua (%)")##      title("Lortuko diren errendimendu maila ezberdinak Tdif desberdinentzako")##      legend(izena,'Location','southoutside')##      legend('boxoff')##      grid on  Errendimendua(potentzia_elek,beropotentzia,Tdif,lim,p,hasierakoK,limK,paso,l,izena,kontador)